The list is 5, 12, 8, 20, 3. The loop deletes nodes whose value is above 10. What is printed?

```c
struct node { int v; struct node *next; };
struct node *mk(int v, struct node *nx){ struct node *n = malloc(sizeof(struct node)); n->v = v; n->next = nx; return n; }
int main(void){ struct node *head = mk(5, mk(12, mk(8, mk(20, mk(3, NULL))))); struct node *p = head; while (p->next) { if (p->next->v > 10) { struct node *t = p->next; p->next = t->next; free(t); } else p = p->next; } for (p = head; p; p = p->next) printf("%d ", p->v); return 0; }
```

push_bad and push_good both try to put 1 at the front of the list 4, 7, 9. What is printed?

```c
struct node { int v; struct node *next; };
struct node *mk(int v, struct node *nx){ struct node *n = malloc(sizeof(struct node)); n->v = v; n->next = nx; return n; }
int len(struct node *h){ int n = 0; for (; h; h = h->next) n++; return n; }
void push_bad(struct node *head, int v){ struct node *n = mk(v, head); head = n; }
void push_good(struct node **head, int v){ struct node *n = mk(v, *head); *head = n; }
int main(void){ struct node *head = mk(4, mk(7, mk(9, NULL))); push_bad(head, 1); int a = len(head); push_good(&head, 1); printf("%d %d %d", a, len(head), head->v); return 0; }
```
